-- +goose Up
-- P7 Reporting (SRS RPT-02, §10): scheduled reports generated by the job runner and e-mailed to configurable
-- recipients, with a run history. One row per report of the §10 table; administrators (reports.schedule) edit
-- enabled / frequency / time / recipients / language / attachment formats.

CREATE TABLE report_schedule (
  key                TEXT PRIMARY KEY,
  enabled            BOOLEAN NOT NULL DEFAULT false,
  frequency          TEXT NOT NULL CHECK (frequency IN ('daily','weekly','monthly','wage_period')),
  send_time          TEXT NOT NULL DEFAULT '06:30' CHECK (send_time ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'),
  day_of_week        INTEGER NOT NULL DEFAULT 1 CHECK (day_of_week BETWEEN 1 AND 7),     -- ISO: 1 = Monday
  day_of_month       INTEGER NOT NULL DEFAULT 1 CHECK (day_of_month BETWEEN 1 AND 28),
  plant_id           TEXT REFERENCES "Plant"(id) ON DELETE SET NULL,                     -- NULL = every site
  language           TEXT NOT NULL DEFAULT '' CHECK (language IN ('','en','am','rw','fr')), -- '' = each recipient's language
  formats            TEXT[] NOT NULL DEFAULT '{pdf,xlsx}',
  recipient_user_ids TEXT[] NOT NULL DEFAULT '{}',
  recipient_roles    TEXT[] NOT NULL DEFAULT '{}',
  recipient_emails   TEXT[] NOT NULL DEFAULT '{}',
  last_slot_at       TIMESTAMP(3),
  updated_by         TEXT REFERENCES "User"(id) ON DELETE SET NULL,
  updated_at         TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CHECK (formats <@ ARRAY['pdf','xlsx','csv']::text[] AND cardinality(formats) >= 1)
);

CREATE TABLE report_run (
  id              TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text,
  schedule_key    TEXT NOT NULL REFERENCES report_schedule(key) ON DELETE CASCADE,
  trigger         TEXT NOT NULL CHECK (trigger IN ('schedule','manual','retry')),
  status          TEXT NOT NULL CHECK (status IN ('queued','running','retrying','success','partial','failed','skipped')),
  slot_at         TIMESTAMP(3),                    -- the schedule slot (NULL for "send now")
  period_from     DATE NOT NULL,
  period_to       DATE NOT NULL,
  attempts        INTEGER NOT NULL DEFAULT 0,
  next_attempt_at TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  recipients      JSONB NOT NULL DEFAULT '[]'::jsonb,  -- [{email,name,userId,lang,status,reason}]
  attachments     JSONB NOT NULL DEFAULT '[]'::jsonb,  -- [{name,format,bytes,lang,plant}]
  cutoff          JSONB,                               -- RPT-06 statement at generation time
  error           TEXT,
  requested_by    TEXT REFERENCES "User"(id) ON DELETE SET NULL,
  started_at      TIMESTAMP(3),
  finished_at     TIMESTAMP(3),
  created_at      TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE UNIQUE INDEX report_run_slot_idx ON report_run (schedule_key, slot_at) WHERE slot_at IS NOT NULL;
CREATE INDEX report_run_key_created_idx ON report_run (schedule_key, created_at DESC);
CREATE INDEX report_run_due_idx ON report_run (next_attempt_at) WHERE status IN ('queued','retrying');

